#include "hdf5.h"
#include <stdio.h>
int main(){
 hid_t f=H5Fcreate("/workspace/base.h5", H5F_ACC_TRUNC, H5P_DEFAULT, H5P_DEFAULT);
 hsize_t dims[1]={1}; hid_t space=H5Screate_simple(1,dims,NULL);
 int val=42; hid_t d=H5Dcreate2(f,"x",H5T_NATIVE_INT,space,H5P_DEFAULT,H5P_DEFAULT,H5P_DEFAULT);
 H5Dwrite(d,H5T_NATIVE_INT,H5S_ALL,H5S_ALL,H5P_DEFAULT,&val);
 const char *s="double";
 hid_t atype=H5Tcopy(H5T_C_S1); H5Tset_size(atype,6); H5Tset_strpad(atype,H5T_STR_NULLTERM);
 hid_t aspace=H5Screate(H5S_SCALAR);
 hid_t a=H5Acreate2(d,"MATLAB_class",atype,aspace,H5P_DEFAULT,H5P_DEFAULT);
 H5Awrite(a,atype,s);
 H5Aclose(a); H5Sclose(aspace); H5Tclose(atype); H5Dclose(d); H5Sclose(space); H5Fclose(f); return 0;
}
